// Actual pinned LVGL renderer + native pointer; synthetic real ImuSample.
#include <lvgl.h>
#include "../trailguide_v3/ui.h"
#include <cassert>
#include <cstdio>
#include <initializer_list>
static lv_color_t buffer[360*20],pixels[360*360];
static unsigned seed=7,events=0;
static uint32_t rng(void *p){auto &s=*static_cast<unsigned*>(p);return s=s*1664525u+1013904223u;}
static void flush(lv_disp_drv_t *d,const lv_area_t *a,lv_color_t *c){for(int y=a->y1;y<=a->y2;++y)for(int x=a->x1;x<=a->x2;++x)pixels[y*360+x]=*c++;lv_disp_flush_ready(d);}
static void advance(unsigned ms){for(unsigned i=0;i<ms;i+=10){lv_tick_inc(10);lv_timer_handler();}lv_obj_update_layout(lv_scr_act());}
static lv_point_t point;static bool pressed=false;
static void touch(lv_indev_drv_t *,lv_indev_data_t *d){d->point=point;d->state=pressed?LV_INDEV_STATE_PRESSED:LV_INDEV_STATE_RELEASED;}
template<class U> static void frame(U &u,float x=0,float z=1,unsigned dt=20,float rate=0){advance(dt);v3::ImuSample s;s.valid=true;s.at_ms=lv_tick_get();s.acc_g[0]=x;s.acc_g[2]=z;s.gyr_dps[1]=rate;bool hit=false;u.sample(s,s.at_ms,true,&hit);events+=hit;}
template<class U> static void quiet(U &u,unsigned n=26,float z=1){while(n--)frame(u,0,z);}
template<class U> static void burst(U &u,unsigned n=55,float z=1){for(unsigned i=0;i<n;++i)frame(u,i%2? -1.1f:1.1f,z);}
static void classic(){v3app::Ui u(rng,&seed,malloc,free);u.instant=true;u.render();quiet(u);burst(u);assert(events==1 && "Classic shake must dispatch exactly one draw");assert(u.model.view==v3app::View::Card&&u.model.mode==v3app::Mode::Ask);burst(u,250);assert(events==1);puts("PASS Classic Home shake -> Ask exactly once; continuous rattle latched");}
static void coaching(){events=0;v3app::CoachUi c(rng,&seed,malloc,free);c.enterCompass();quiet(c);burst(c);assert(events==1 && "Coaching shake must draw one opener");assert(!c.compassHome&&c.model.current.screen==v3app::Screen::Opening&&c.busy());burst(c,600);assert(events==1);assert(!c.busy());puts("PASS Coaching compass -> opener, real 6s reveal, continuous rattle across busy expiry stays one");}
template<class U> static void repaintCancels(U &u){events=0;quiet(u);burst(u,30);u.render();burst(u,30);assert(events==0&&"Repaint must cancel partial shake, not recreate fired latch");quiet(u);burst(u);assert(events==1);u.render();burst(u,250);assert(events==1);}
static void lifecycle(){v3app::Ui u(rng,&seed,malloc,free);u.instant=true;u.render();repaintCancels(u);v3app::CoachUi c(rng,&seed,malloc,free);c.instant=true;c.enterCompass();repaintCancels(c);puts("PASS render cancels partial intent, preserves fired latch in both owners");}
template<class U> static void pointerCancels(U &u){events=0;quiet(u);burst(u,30);point={180,180};pressed=true;advance(40);assert(!u.eligible());pressed=false;advance(40);burst(u,30);assert(events==0&&"Real pointer contact without intervening IMU calls must cancel partial shake");quiet(u);burst(u);assert(events==1);}
static void pointerLifecycle(){v3app::Ui u(rng,&seed,malloc,free);u.instant=true;u.model.draw(v3app::Mode::Try);u.render();pointerCancels(u);assert(u.model.mode==v3app::Mode::Try);v3app::CoachUi c(rng,&seed,malloc,free);c.instant=true;c.model.enter();c.render();pointerCancels(c);puts("PASS real LVGL press/release cancels partial shake; Classic Try mode preserved");}
static bool black(){lv_refr_now(nullptr);for(auto p:pixels)if(p.full)return false;return true;}
template<class U> static void negatives(U &u){events=0;quiet(u);burst(u,20);quiet(u,30);assert(events==0);for(unsigned i=0;i<100;++i)frame(u,i%2?-1.f:1.f,0,20,600);assert(events==0&&"Gravity-only high-rate rotation is not a shake");for(unsigned i=0;i<100;++i)frame(u,i%2?-1.1f:1.1f,1,20,v3::GyroSafetyDps);assert(events==0&&"Physical gyro safety bound still cancels");quiet(u);for(unsigned i=0;i<100;++i)frame(u,i%2?-1.1f:1.1f,1,20,200.f+float(i%6)*100.f);assert(events==1&&"Sustained translation with ordinary wrist rotation must draw once");burst(u,250);assert(events==1);quiet(u);burst(u);assert(events==2);}
static void negativeCases(){ {v3app::Ui u(rng,&seed,malloc,free);u.instant=true;u.render();negatives(u);} {v3app::CoachUi c(rng,&seed,malloc,free);c.instant=true;c.enterCompass();negatives(c);}puts("PASS short burst, gravity-only rotation and sensor-bound motion rejected in both modes; mixed translation/rotation draws once with quiet rearm");}
template<class U> static void invalidFrames(U &u){events=0;quiet(u);for(unsigned i=0;i<80;++i){frame(u,i%2?-1.1f:1.1f,1,i%2?30:10);v3::ImuSample s;s.at_ms=lv_tick_get();s.valid=false;bool hit=false;u.sample(s,lv_tick_get(),true,&hit);assert(!hit);}assert(events==1&&"Invalid NotReady pauses must not cancel eligible burst");burst(u,130);quiet(u,26);burst(u);assert(events==2&&"Cooldown followed by fresh quiet must permit rearm");}
static void notReady(){ {v3app::Ui u(rng,&seed,malloc,free);u.instant=true;u.render();invalidFrames(u);} {v3app::CoachUi c(rng,&seed,malloc,free);c.instant=true;c.enterCompass();invalidFrames(c);}puts("PASS variable fresh timestamps + retained-timestamp invalid NotReady pauses; cooldown and quiet rearm");}
template<class U> static void duplicateFault(U &u){events=0;quiet(u);burst(u,30);v3::ImuSample s;s.valid=true;s.at_ms=lv_tick_get();s.acc_g[0]=1.1f;s.acc_g[2]=1;u.sample(s,s.at_ms,false);burst(u,30);assert(events==0);quiet(u);burst(u,30);s.at_ms=lv_tick_get();u.sample(s,s.at_ms+70,true);burst(u,30);assert(events==0);quiet(u);burst(u,30);advance(200);burst(u,30);assert(events==0);quiet(u);burst(u);assert(events==1);}
static void freshness(){ {v3app::Ui u(rng,&seed,malloc,free);u.instant=true;u.render();duplicateFault(u);} {v3app::CoachUi c(rng,&seed,malloc,free);c.instant=true;c.enterCompass();duplicateFault(c);}puts("PASS availability loss on duplicate, stale duplicate, long fresh gap cancel intent before legacy return");}
template<class U> static void blankShake(U &u){events=0;quiet(u,45);quiet(u,11,-1);assert(black());burst(u,55,-1);assert(events==1&&!black());quiet(u,12);burst(u,200);assert(events==1);}
template<class U> static void normalFlip(U &u){events=0;quiet(u,45);quiet(u,11,-1);assert(black());quiet(u,11);assert(events==1&&!black());burst(u);assert(events==1&&"Flip draw must cancel partial shake and require quiet");}
static void arbitration(){ {v3app::Ui u(rng,&seed,malloc,free);u.instant=true;u.render();blankShake(u);} {v3app::CoachUi c(rng,&seed,malloc,free);c.instant=true;c.enterCompass();blankShake(c);} {v3app::Ui u(rng,&seed,malloc,free);u.instant=true;u.render();normalFlip(u);} {v3app::CoachUi c(rng,&seed,malloc,free);c.instant=true;c.enterCompass();normalFlip(c);}puts("PASS actual black pixels restore with one shake draw; return-up cannot finish old flip; ordinary flip still draws once and disarms shake");}
static void contexts(){
 for(auto screen:{v3app::Screen::Question,v3app::Screen::Experiment,v3app::Screen::Guide,v3app::Screen::Options,v3app::Screen::Closing,v3app::Screen::Picker,v3app::Screen::Reminders}){v3app::CoachUi c(rng,&seed,malloc,free);c.instant=true;c.model.enter();c.model.path(0);c.model.current.screen=screen;c.render();auto before=c.model.current;auto n=c.model.draws;events=0;quiet(c);burst(c,100);assert(events==0&&c.model.draws==n&&c.model.current.index==before.index&&c.model.current.path==before.path&&c.model.current.screen==screen);}
 for(bool options:{false,true}){v3app::Ui u(rng,&seed,malloc,free);u.instant=true;if(options){u.render();u.perform(v3app::Ui::Action::Options);}else{u.model.draw(v3app::Mode::Try);u.model.guide();u.render();}auto index=u.model.index;auto view=u.model.view;events=0;quiet(u);burst(u,100);assert(events==0&&u.model.index==index&&u.model.view==view);}
 {v3app::Ui u(rng,&seed,malloc,free);u.perform(v3app::Ui::Action::Ask);auto index=u.model.index;events=0;quiet(u);burst(u);assert(u.busy()&&events==0&&u.model.index==index);}
 puts("PASS excluded Classic Guide/Options and all seven non-Opening Coaching screens preserve exact path/index; reveal busy blocks shake");
}
template<class U> static void dragGate(U &u){events=0;quiet(u);burst(u,30);lv_label_set_text(u.body,"One\nTwo\nThree\nFour\nFive\nSix\nSeven\nEight\nNine\nTen\nEleven\nTwelve");advance(30);point={180,210};pressed=true;advance(40);for(int i=0;i<5;++i){point.y-=12;advance(30);}assert(lv_obj_get_scroll_y(u.scroll)>0);assert(!u.eligible());burst(u,60);assert(events==0);pressed=false;advance(40);burst(u,30);assert(events==0);}
static void scrollGate(){ {v3app::Ui u(rng,&seed,malloc,free);u.instant=true;u.model.draw(v3app::Mode::Ask);u.render();dragGate(u);} {v3app::CoachUi c(rng,&seed,malloc,free);c.instant=true;c.model.enter();c.render();dragGate(c);}puts("PASS real native pointer drag scrolls text and suppresses shake while contact/scrolling; partial intent cannot resume");}
template<class U> static void threshold(U &u){events=0;quiet(u,21);burst(u,45);assert(events==0&&"Less than 900ms burst evidence cannot draw");frame(u,-1.1f);assert(events==1&&"900 credited ms and >=10 alternating peaks must draw");}
static void thresholds(){ {v3app::Ui u(rng,&seed,malloc,free);u.instant=true;u.render();threshold(u);} {v3app::CoachUi c(rng,&seed,malloc,free);c.instant=true;c.enterCompass();auto n=c.model.draws;threshold(c);assert(c.model.draws==n+1);}puts("PASS 400ms quiet / 900ms fresh burst boundary in actual UI samples, one Coaching model increment");}
static lv_obj_t *findText(lv_obj_t *o,const char *s){if(lv_obj_check_type(o,&lv_label_class)&&!strcmp(lv_label_get_text(o),s))return o;for(unsigned i=0;i<lv_obj_get_child_cnt(o);++i)if(auto *p=findText(lv_obj_get_child(o,i),s))return p;return nullptr;}
static void tap(int x,int y){point={lv_coord_t(x),lv_coord_t(y)};pressed=true;advance(40);pressed=false;advance(40);}
static void tapText(lv_obj_t *root,const char *s){auto *o=findText(root,s);assert(o);lv_area_t a;lv_obj_get_coords(lv_obj_get_parent(o),&a);tap((a.x1+a.x2)/2,(a.y1+a.y2)/2);}
static void pointerContexts(){const int xy[6][2]={{180,44},{296,118},{296,242},{180,316},{64,242},{64,118}};for(int p=0;p<6;++p){v3app::Ui u(rng,&seed,malloc,free);u.instant=true;u.perform(v3app::Ui::Action::Coaching);events=0;quiet(u);burst(u,30);tap(xy[p][0],xy[p][1]);auto before=u.coach.model.current;auto n=u.coach.model.draws;assert(before.screen==v3app::Screen::Question&&before.path==p);burst(u,100);assert(events==0&&u.coach.model.draws==n&&u.coach.model.current.index==before.index);tapText(u.coach.root,"Guide me");quiet(u);burst(u);assert(events==0&&u.coach.model.current.screen==v3app::Screen::Guide);tapText(u.coach.root,"Back");assert(u.coach.model.current.path==p&&u.coach.model.current.index==before.index);tapText(u.coach.root,"Try (optional)");auto experiment=u.coach.model.current;quiet(u);burst(u);assert(events==0&&u.coach.model.current.index==experiment.index&&u.coach.model.current.path==p);tapText(u.coach.root,"Release");quiet(u);burst(u);assert(events==0&&u.coach.model.current.screen==v3app::Screen::Closing&&u.coach.model.draws==n);}puts("PASS Ui delegation + all six real pointer path choices interrupt partial burst; Question/Guide/Back/Experiment/Closing exact context preserved");}
static void *noMemory(size_t){return nullptr;}
static void cancellationAndFallback(){
 {v3app::Ui u(rng,&seed,malloc,free);u.instant=true;u.render();events=0;quiet(u);burst(u);assert(events==1);auto index=u.model.index;u.perform(v3app::Ui::Action::Instant);u.perform(v3app::Ui::Action::Instant);burst(u,150);u.perform(v3app::Ui::Action::Home);u.perform(v3app::Ui::Action::Options);u.perform(v3app::Ui::Action::Back);burst(u,150);assert(events==1&&u.model.view==v3app::View::Home);quiet(u);burst(u);assert(events==2&&u.model.view==v3app::View::Card&&u.model.index!=index);}
 {v3app::CoachUi c(rng,&seed,malloc,free);c.instant=true;c.enterCompass();events=0;quiet(c);burst(c);assert(events==1);auto n=c.model.draws;c.perform(v3app::CoachUi::Action::Options);c.perform(v3app::CoachUi::Action::Instant);c.perform(v3app::CoachUi::Action::Instant);c.perform(v3app::CoachUi::Action::Back);burst(c,300);assert(events==1&&c.model.draws==n);quiet(c);burst(c);assert(events==2&&c.model.draws==n+1);}
 {v3app::Ui u(rng,&seed,noMemory,free);u.render();events=0;quiet(u);burst(u);assert(events==1&&u.fallback&&!u.busy()&&!black());burst(u,300);assert(events==1);}
 {v3app::CoachUi c(rng,&seed,noMemory,free);c.enterCompass();events=0;quiet(c);burst(c);assert(events==1&&c.fallback&&!c.busy()&&!black());burst(c,300);assert(events==1);}
 puts("PASS Instant toggles, navigation/cancel and reveal allocation fallback preserve latch until fresh quiet; fallback remains readable");
}
template<class U> static void revealTiming(U &u){events=0;quiet(u,21);burst(u,46);assert(events==1&&u.busy()&&!u.fallback);advance(5990);assert(u.busy());advance(10);assert(!u.busy()&&lv_obj_has_flag(u.backButton,LV_OBJ_FLAG_HIDDEN));advance(4990);assert(lv_obj_has_flag(u.backButton,LV_OBJ_FLAG_HIDDEN));advance(10);assert(!lv_obj_has_flag(u.backButton,LV_OBJ_FLAG_HIDDEN));}
static void reveal(){ {v3app::Ui u(rng,&seed,malloc,free);u.render();revealTiming(u);} {v3app::CoachUi c(rng,&seed,malloc,free);c.enterCompass();revealTiming(c);}puts("PASS shake uses exact real 6000ms reveal + 5000ms readable hold in both modes");}
int main(){setbuf(stdout,nullptr);lv_init();lv_disp_draw_buf_t b;lv_disp_draw_buf_init(&b,buffer,nullptr,360*20);lv_disp_drv_t d;lv_disp_drv_init(&d);d.hor_res=d.ver_res=360;d.draw_buf=&b;d.flush_cb=flush;lv_disp_drv_register(&d);lv_indev_drv_t input;lv_indev_drv_init(&input);input.type=LV_INDEV_TYPE_POINTER;input.read_cb=touch;lv_indev_drv_register(&input);classic();coaching();lifecycle();pointerLifecycle();negativeCases();notReady();freshness();arbitration();contexts();scrollGate();thresholds();pointerContexts();cancellationAndFallback();reveal();}
